111	    private final VisitMapper visitMapper;
112	
113	    public OwnerRestControllerV1(ClinicService clinicService,
114	                                 OwnerMapper ownerMapper,
115	                                 PetMapper petMapper,
116	                                 VisitMapper visitMapper) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        validateRequiredFields(ownerFieldsDto);
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
155	        LocalDate effectiveDate = owner.getRegistrationDate() == null
156	            ? LocalDate.now()
157	            : owner.getRegistrationDate();
158	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
159	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
160	        rejectWhenCityAtCapacity(owner.getCity());
161	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
162	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
163	        rejectDuplicateTelephone(telephone);
164	        owner.setTelephone(telephone);
165	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
166	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
167	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
168	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
169	        this.clinicService.saveOwner(owner);
170	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
171	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    /**
179	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
180	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
181	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
182	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
183	     *
184	     * @param city     the owner's city
185	     * @param lastName the owner's last name
186	     * @return the assigned customer code
187	     */
188	    private String nextCustomerCode(String city, String lastName) {
189	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
190	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
191	        int sequence = (int) this.clinicService.findAllOwners().stream()
192	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
193	            .count() + 1;
194	        return String.format("%s-%s-%04d", city3, last3, sequence);
195	    }
